    <div class="overflow-hidden rounded-lg border border-zinc-200 dark:border-zinc-700" wire:poll.5s><div class="border-b border-zinc-200 p-4 dark:border-zinc-700"><flux:heading level="2">Historial de impresión</flux:heading><p class="mt-1 text-xs text-zinc-500">“Enviado” confirma el envío de datos, no la salida física del papel. Los errores no se reintentan automáticamente. Si un envío sigue en curso después de un minuto, actualiza su estado y revisa el papel.</p></div><div class="divide-y divide-zinc-200 px-4 dark:divide-zinc-700">@forelse($historial as $trabajo)<div class="space-y-2 py-4" wire:key="print-job-{{ $trabajo->id }}"><div class="flex flex-wrap items-start justify-between gap-3"><div class="text-sm"><p class="font-medium">#{{ $trabajo->id }} · {{ ['comanda'=>'Comanda / aviso','precuenta'=>'Precuenta','ticket'=>'Ticket de cobro'][$trabajo->tipo->value] }}{{ $trabajo->reimpresion_de_id ? ' · copia de #'.$trabajo->reimpresion_de_id : '' }}</p><p class="mt-1 text-xs text-zinc-500">{{ $trabajo->configuracion['nombre'] ?? $trabajo->impresora->nombre }} · {{ $trabajo->usuario_nombre }} · {{ $trabajo->created_at?->format('d/m/Y H:i') }}</p></div><flux:badge size="sm" :color="match($trabajo->estado->value){'enviado'=>'green','error'=>'red',default=>'amber'}">{{ ['pendiente'=>'Pendiente','procesando'=>'En curso','enviado'=>'Enviado','error'=>'Error','resultado_incierto'=>'Resultado sin confirmar'][$trabajo->estado->value] }}</flux:badge></div>@if($trabajo->ultimo_error)<p class="text-xs text-red-700 dark:text-red-300">{{ $trabajo->ultimo_error }}</p>@endif @if($trabajo->motivo_reimpresion)<p class="text-xs text-zinc-500">Motivo de copia: {{ $trabajo->motivo_reimpresion }}</p>@endif<div class="flex gap-2"><flux:button size="sm" wire:click="viewJob({{ $trabajo->id }})">Ver documento</flux:button>@if(!in_array($trabajo->estado->value,['pendiente','procesando'],true))@can('impresion.reimprimir')<flux:button size="sm" wire:click="openCopy({{ $trabajo->id }})">Preparar