    <flux:modal wire:model="showPreview" class="w-full md:max-w-lg"><div class="space-y-4"><div><flux:heading level="2">{{ $puedeEnviar ? ($copiaId ? 'Vista previa de copia' : 'Vista previa') : 'Documento registrado' }}</flux:heading><flux:text class="mt-1">{{ $nombreImpresora }} · {{ $ancho }} mm{{ $trabajoVisto ? ' · impresión #'.$trabajoVisto : '' }}</flux:text></div>@if($errors->any())<div role="alert" class="rounded border border-red-300 bg-red-50 p-3 text-sm text-red-800 dark:bg-red-950 dark:text-red-200">@foreach($errors->all() as $error)<p>{{ $error }}</p>@endforeach</div>@endif<div class="max-h-[55vh] overflow-auto rounded border border-zinc-200 bg-white p-3 text-black"><pre class="mx-auto w-fit text-[10px] leading-relaxed sm:text-xs" data-print-preview>{{ $texto }}</pre></div>@if($puedeEnviar)@if($copiaId)<flux:textarea wire:model="motivoCopia" label="Motivo de la reimpresión" aria-label="Motivo de la reimpresión" rows="2" maxlength="500"/><p class="text-xs text-amber-700 dark:text-amber-300">Verifica primero el papel. La copia conserva el documento histórico y queda identificada; no es un pedido nuevo.</p>@endif<flux:button class="w-full" variant="primary" wire:click="requestConfirmation" wire:loading.attr="disabled">{{ $copiaId ? 'Imprimir copia' : 'Imprimir documento' }}</flux:button>@else<p class="text-xs text-zinc-500">Se conserva la información usada al solicitar esta impresión. Para otro ejemplar utiliza “Preparar copia” desde el historial.</p>@endif</div></flux:modal>
